// Para cada lead, calcular qué email del nurturing toca enviar hoy.
// Sequence: T+0 entrega (ya enviado en captura), T+1, T+3, T+5, T+7, T+10, T+14.
// Tras T+14 sin acción → status='no-response'.

const SEQUENCE = [
  { day: 1,  template: 'edu_01_que_es_marli',     subject: 'Cómo recuperar 8 horas a la semana sin contratar a nadie' },
  { day: 3,  template: 'story_02_caso_lucia',     subject: 'Lucía atendía 22 pacientes con 9 horas/sem de admin. Mira lo que hizo.' },
  { day: 5,  template: 'caso_03_clinica_madrid',  subject: 'Una clínica con 5 psicólogos, todos en el mismo sistema' },
  { day: 7,  template: 'eco_04_math_498',         subject: 'Las cuentas: 498€ vs 1.500€ al año. Mira el desglose' },
  { day: 10, template: 'cta_05_video_demo',       subject: '¿25 minutos para ver si Marli encaja en tu consulta?' },
  { day: 14, template: 'cta_06_escasez_oferta',   subject: 'Última semana del precio actual (después sube)' }
];

const now = new Date();
const out = [];

for (const lead of $input.all()) {
  const props = lead.json.properties || {};
  const captura = props['Fecha Captura']?.date?.start;
  if (!captura) continue;

  const daysSince = Math.floor((now - new Date(captura)) / (1000 * 60 * 60 * 24));

  // Detectar qué email del sequence toca (si hay alguno hoy exacto).
  const slot = SEQUENCE.find(s => s.day === daysSince);
  if (!slot) {
    // Si pasó T+14 y status sigue 'capturado'/'nurturing' → marcar no-response.
    if (daysSince > 14) {
      out.push({
        action: 'mark_no_response',
        page_id: lead.json.id,
        email: props.Email?.title?.[0]?.plain_text
      });
    }
    continue;
  }

  out.push({
    action: 'send_email',
    page_id: lead.json.id,
    email: props.Email?.title?.[0]?.plain_text,
    nombre: props.Nombre?.rich_text?.[0]?.plain_text || '',
    template: slot.template,
    subject: slot.subject,
    day: slot.day
  });
}

return out.map(item => ({ json: item }));

